window.BVC_RESEARCH_CONTENT={"schema":"JBC_PERSON_READER_CONTENT_v2","researchId":"JBC_ISAAC_PERSON_PROFILE_WORBS_20261005_01","version":"v1.0","sha256":"e75c9378dab8794728edf4021aecb986cf285ec63818afa067330a059bc2bf66","section":"APPROVED PERSON READER PROJECTION","summary":"이삭은 아브라함과 사라에게 약속된 아들이며, 아브라함에게 주어진 언약의 약속을 야곱 세대로 이어 주는 족장이다. 그의 생애는 모리아의 시험, 리브가와의 결혼, 자녀를 위한 기도, 그랄의 기근과 우물 분쟁, 브엘세바에서의 약속 재확인, 에서와 야곱을 향한 축복으로 이어진다. 특히 창세기 26장은 이삭을 단순한 수동적 인물이 아니라 약속을 따라 머물고, 우물을 다시 파며, 갈등 속에서 이동하고, 예배와 평화의 관계를 세우는 독자적 행위자로 보여 준다.","facts":[{"k":"parents","v":"아브라함, 사라"},{"k":"spouse","v":"리브가"},{"k":"children","v":"에서, 야곱"},{"k":"half_brother","v":"이스마엘"},{"k":"major_activity_regions","v":["네게브/남방","브엘라해로이 주변","그랄과 그랄 골짜기","르호봇으로 불린 우물 지역","브엘세바","마므레/헤브론"]},{"k":"major_events","v":["출생과 할례","모리아의 시험/결박","리브가와의 결혼","리브가를 위한 기도와 쌍둥이 출생","그랄 체류","우물 분쟁","브엘세바 언약","야곱/에서 축복 사건"]},{"k":"theological_role","v":["약속의 아들","언약 계승자","아브라함과 야곱 사이의 족장","신약의 약속·선택·믿음 논증에 사용되는 인물"]}],"note":"연대 수치는 창세기 자체의 상대 연령 자료(결혼 때 40세, 쌍둥이 출생 때 60세, 사망 180세)는 본문 데이터로 기록할 수 있으나, 이를 현대 절대연대 BCE로 환산하여 fact로 확정하지 않는다.","identity":{"name_ko":"이삭","name_en":"Isaac","original_name":"יִצְחָק","transliteration":"Yiṣḥāq / Yitzḥaq / Yitzhak","pronunciation_ko":"이츠하크","greek_name":"Ἰσαάκ","greek_transliteration":"Isaak","greek_pronunciation_ko":"이사아크"},"intro":{"concise_intro":"아브라함에게 약속된 아들이며, 야곱에게 언약의 약속을 전달하는 중간 족장이다."},"quick_facts_extra":[{"key":"name_meaning","label":"이름의 뜻","value":"그가 웃는다/웃을 것이다","certainty":"LIKELY"},{"key":"core_role","label":"핵심 역할","value":["약속의 아들","언약 계승자","아브라함과 야곱 사이의 족장"]},{"key":"representative_passages","label":"대표 본문","value":["창 21","창 22","창 24","창 25","창 26","창 27","창 28"]}],"narrative_sections":[{"title":"약속의 아들이 태어나다","passages":[["gen",17,15,21],["gen",18,9,15],["gen",21,1,7]],"paragraphs":["이삭의 가장 기본적인 정체성은 인간의 자연적 가능성보다 하나님의 약속에 의해 주어진 아들이라는 점이다.","창 17:19–21은 언약이 이삭과 그의 후손에게 세워질 것이라고 명시하고, 창 21장은 그 약속의 성취를 서술한다."]},{"title":"모리아 산을 오르다","passages":[["gen",22,1,19]],"paragraphs":["모리아 시험이다. 2, 3, 6, 7, 9절에 이름이 직접 나오며 나머지 절은 아브라함 중심 서술 속 이삭이 계속 핵심 대상이다.","아브라함의 사랑하는 아들, 제물로 묶였다가 보존됨"]},{"title":"리브가와 새로운 가정을 이루다","passages":[["gen",24,1,67]],"paragraphs":["배우자 확보 서사이다. 대부분은 아브라함의 종과 리브가 중심이며, 이삭은 목표 인물로 간접 연결되다가 62절 이후 장면에 직접 등장한다.","혼인 서사의 목표 인물, 62절 이후 직접 행위자"]},{"title":"아내를 위해 기도하다","passages":[["gen",25,19,26]],"paragraphs":["이삭 톨레도트의 시작, 리브가를 위한 기도, 에서와 야곱 출생, 부모의 편애이다.","불임 상황에서 기도하는 남편, 에서·야곱의 아버지"]},{"title":"기근 속에서 그랄에 머물다","passages":[["gen",26,1,17]],"paragraphs":["창 26:2–5, 24에서 아브라함에게 주어진 땅·자손·복의 약속이 이삭에게 직접 재진술된다.","기근 속 하나님의 명령에 따라 그랄에 머묾"],"related_places":["JBC-CR-PLACE-GERAR-001"]},{"title":"우물을 파고 또 물러나다","passages":[["gen",26,18,22]],"paragraphs":["아브라함의 우물을 다시 파고 갈등 속에서 이동","연구층에서는 갈등 속 공간 확보와 평화적 공존의 서사로 기술하는 것이 안전하다."]},{"title":"브엘세바에서 다시 약속을 듣다","passages":[["gen",26,23,33]],"paragraphs":["브엘세바에서 하나님이 다시 약속을 확인하시자 이삭은 제단을 쌓고 예배하며, 과거에 떠나라고 했던 아비멜렉 일행과 평화 조약을 맺는다.","약속을 듣고 제단을 쌓고 여호와의 이름을 부름"],"related_places":["JBC-CR-PLACE-BEERSHEBA-001"]},{"title":"축복을 둘러싼 가족의 갈등","passages":[["gen",27,1,40]],"paragraphs":["야곱과 에서 축복 사건에서 이삭이 축복의 주체이자 속임의 대상이다.","본문은 가족의 편애와 속임을 정당화하지 않는다."]},{"title":"언약을 다음 세대로 넘기다","passages":[["gen",28,1,5],["gen",35,27,29]],"paragraphs":["창 28:3–4에서 이삭은 야곱에게 “아브라함에게 허락하신 복”의 계보적 방향을 명시적으로 연결한다.","마므레의 이삭, 죽음과 장사이다."]}],"theological_summary":["이삭은 약속으로 주어지고 보존된 아들이며, 아브라함의 언약 약속을 직접 재확인받아 야곱 세대로 전달하는 족장이다. 창세기 26장은 그가 땅과 우물, 갈등과 평화 속에서 그 약속을 실제 삶으로 통과하는 독자적 행위자임을 보여 준다.","아브라함에게 주어진 약속은 이삭에게 재확인되고 야곱에게 이어진다. 이 연속성의 궁극적 주체는 족장들의 완전성이 아니라 약속을 주시고 보존하시는 하나님이다."],"related_places":[{"label":"그랄","stable_id":"JBC-CR-PLACE-GERAR-001"},{"label":"브엘세바","stable_id":"JBC-CR-PLACE-BEERSHEBA-001"}]};
